59|static void
60|ParseOneInput(XML_Parser p, const uint8_t *data, size_t size) {
61|  // Set the hash salt using siphash to generate a deterministic hash.
62|  struct sipkey *key = sip_keyof(hash_key);
63|  XML_SetHashSalt(p, (unsigned long)siphash24(data, size, key));
64|  (void)sip24_valid;
65|
66|  XML_SetUserData(p, p);
67|  XML_SetElementHandler(p, start, end);
68|  XML_SetCharacterDataHandler(p, may_stop_character_handler);
69|  assert(size <= INT_MAX);
70|  XML_Parse(p, (const XML_Char *)data, (int)size, 0);
71|  if (XML_Parse(p, (const XML_Char *)data, (int)size, 1) == XML_STATUS_ERROR) {
72|    XML_ErrorString(XML_GetErrorCode(p));
73|  }
74|  XML_GetCurrentLineNumber(p);
75|  if (size % 2) {
76|    XML_ParserReset(p, NULL);
77|  }
