80|int
81|LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
82|  XML_Parser parentParser = XML_ParserCreate(xstr(ENCODING_FOR_FUZZING));
83|  assert(parentParser);
84|  ParseOneInput(parentParser, data, size);
85|  // not freed yet, but used later and freed then
86|
87|  XML_Parser namespaceParser = XML_ParserCreateNS(NULL, '!');
88|  assert(namespaceParser);
89|  ParseOneInput(namespaceParser, data, size);
90|  XML_ParserFree(namespaceParser);
91|
92|  XML_Parser externalEntityParser
93|      = XML_ExternalEntityParserCreate(parentParser, "e1", NULL);
94|  if (externalEntityParser != NULL) {
95|    ParseOneInput(externalEntityParser, data, size);
96|    XML_ParserFree(externalEntityParser);
97|  }
98|
99|  XML_Parser externalDtdParser
100|      = XML_ExternalEntityParserCreate(parentParser, NULL, NULL);
101|  if (externalDtdParser != NULL) {
102|    ParseOneInput(externalDtdParser, data, size);
103|    XML_ParserFree(externalDtdParser);
104|  }
105|
106|  // finally frees this parser which served as parent
107|  XML_ParserFree(parentParser);
108|  return 0;
109|}

