1047|gather_time_entropy(void) {
1048|#  ifdef _WIN32
1049|  FILETIME ft;
1050|  GetSystemTimeAsFileTime(&ft); /* never fails */
1051|  return ft.dwHighDateTime ^ ft.dwLowDateTime;
1052|#  else
1053|  struct timeval tv;
1054|  int gettimeofday_res;
1055|
1056|  gettimeofday_res = gettimeofday(&tv, NULL);
1057|
1058|#    if defined(NDEBUG)
1059|  (void)gettimeofday_res;
1060|#    else
1061|  assert(gettimeofday_res == 0);
1062|#    endif /* defined(NDEBUG) */
1063|
1064|  /* Microseconds time is <20 bits entropy */
1065|  return tv.tv_usec;
1066|#  endif
1067|}

